    I sw, lw, on_p, on_q, off_p, off_q, min_duration, noise, aw, clip, window, minimum;
    double velocity;
    std::array<I, 3> gx, gy, gz;
    double limit;
    std::array<double, 3> qa, qb;
    std::array<double, 2> cluster;
    std::array<double, 3> local, duration;
